package com.technova.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="contacto") public class Contacto { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_contacto") private Long id; private String nombre,email,telefono,asunto,mensaje,estado; private LocalDateTime fecha; public Contacto(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getTelefono(){return telefono;} public void setTelefono(String v){telefono=v;} public String getAsunto(){return asunto;} public void setAsunto(String v){asunto=v;} public String getMensaje(){return mensaje;} public void setMensaje(String v){mensaje=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} }
